'use strict';
var localJarData=null;
var frame=document.getElementById('mozbrowser'),message=document.getElementById('message');
// Deliberately narrow host bridge. Java programs get simulated carrier data only.
var DumbPipe={handleEvent:function(event){var e;try{e=JSON.parse(event.detail.message);}catch(_){return;}if(e.command!=='open')return;var data;if(e.type==='mobileInfo')data={network:{mcc:'460',mnc:'00'},icc:{mcc:'460',mnc:'00',msisdn:'00000000000'}};else if(e.type==='alert'){message.textContent=String(e.message).slice(0,200);return;}else if(e.type==='exit'){message.textContent='Java 程序已退出';return;}else {console.warn('Disabled Java host capability:',e.type);data={type:'error',error:'Unavailable in offline museum'};}setTimeout(function(){frame.contentWindow.postMessage({pipeID:e.pipeID,message:data},location.origin);},0);}};
function launchDemo(){localJarData=null;var id=document.getElementById('demo').value;var cls={snake:'OldSnake',calculator:'PocketCalculator',notes:'PocketNotes'}[id];if(!cls)return;message.textContent='正在启动 '+cls+' · 首次加载约数秒';frame.src='main.html?jars=demos/'+id+'.jar&jad=demos/'+id+'.jad&midletClassName='+cls+'&autosize=1&fontSize=12';}
document.getElementById('run').onclick=launchDemo;
document.getElementById('stop').onclick=function(){frame.src='about:blank';message.textContent='已停止，点击启动重新运行。';};
function key(code,down){if(code===-6){frame.contentDocument.getElementById("header-drawer-button")?.click();return;}if(code===-7){frame.contentDocument.querySelector("#header-ok-button button")?.click();return;}code=({"-1":119,"-2":115,"-3":97,"-4":100,"-5":32,"-6":112,"-7":8})[code]||code;try{var m=frame.contentWindow.MIDP;if(m)(down?m.sendKeyPress:m.sendKeyRelease)(code);}catch(_){}}
document.querySelectorAll('[data-key]').forEach(function(b){b.addEventListener('pointerdown',function(e){e.preventDefault();b.setPointerCapture(e.pointerId);key(Number(b.dataset.key),true);});b.addEventListener('pointerup',function(){key(Number(b.dataset.key),false);});b.addEventListener('pointercancel',function(){key(Number(b.dataset.key),false);});});
var map={ArrowUp:-1,ArrowDown:-2,ArrowLeft:-3,ArrowRight:-4,Enter:-5,F1:-6,F2:-7};
['keydown','keyup'].forEach(function(type){window.addEventListener(type,function(e){if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;var c=map[e.key];if(c===undefined&&/^[0-9*#]$/.test(e.key))c=e.key.charCodeAt(0);if(c!==undefined){e.preventDefault();key(c,type==='keydown');}});});
document.getElementById('jar').onchange=async function(e){var file=e.target.files[0];if(!file)return;if(file.size>8*1024*1024){message.textContent='请导入 8 MB 以内的 JAR。';return;}try{var data=await file.arrayBuffer(),zip=new ZipFile(data);var entry=zip.directory&&Object.keys(zip.directory).find(function(n){return n.toUpperCase()==='META-INF/MANIFEST.MF';});if(Object.keys(zip.directory||{}).length>5000||Object.values(zip.directory||{}).reduce(function(n,x){return n+(x.uncompressed_len||0);},0)>64*1024*1024)throw Error("large archive");if(entry&&zip.directory[entry].uncompressed_len>65536)throw Error("large manifest");var bytes=entry&&zip.read(entry);if(!bytes||bytes.length>65536)throw Error('manifest');var text=new TextDecoder().decode(bytes).replace(/\r\n?/g,'\n').replace(/\n /g,'');var line=text.split('\n').find(function(x){return /^MIDlet-1:\s*/i.test(x);});var cls=line&&line.split(',').pop().trim();if(!cls||!/^[\w.$]+$/.test(cls))throw Error('class');localJarData=data;frame.src='main.html?jars=local.jar&jad=&midletClassName='+encodeURIComponent(cls)+'&autosize=1&fontSize=12';message.textContent='本机运行：'+file.name+' · 不上传';}catch(_){message.textContent='无法读取 MIDlet-1 清单，请选择有效的 Java ME JAR。';}};
launchDemo();

setInterval(function(){try{var c=frame.contentDocument.querySelector("#canvas");if(c&&c.width>0&&c.height>0&&message.textContent.indexOf("正在启动")===0)message.textContent="已载入 · 点屏幕或按键操作";}catch(_){}},1000);
